package android.widget;public class PopupMenu {public static PopupMenu last;android.view.Menu menu=new android.view.Menu();OnMenuItemClickListener listener;public PopupMenu(android.app.Activity a,android.view.View v){last=this;}public android.view.Menu getMenu(){return menu;}public interface OnMenuItemClickListener {boolean onMenuItemClick(android.view.MenuItem i);}public void setOnMenuItemClickListener(OnMenuItemClickListener l){listener=l;}public void show(){}public void select(int id){listener.onMenuItemClick(new android.view.MenuItem(id));}}